#![cfg(feature = "xprec")]
//! The public API against mpmath (ground truth) and SciPy (parity), for
//! `f64` and `xprec::Df64`, plus SciPy's non-finite and zero results.
//!
//! Reference data: `tests/data`, generated by `scripts/gen_specials_reference.py`.
//!
//! The `f64` rows run in every configuration; the `Df64` tests and the `Df64`
//! half of `special_values_match_scipy` need the `xprec` feature (on by
//! default).

#[path = "../src/refdata.rs"]
mod refdata;

use refdata::{error, rows, same, special_values};
use specials::Real;
#[cfg(feature = "xprec")]
use xprec::Df64;

fn eval<T: Real>(name: &str, a: &[T]) -> T {
    match name {
        "gamma" => specials::gamma(a[0]),
        "lgamma" => specials::lgamma(a[0]),
        "rgamma" => specials::rgamma(a[0]),
        "digamma" => specials::digamma(a[0]),
        "zeta" => specials::zeta(a[0], a[1]),
        "beta" => specials::beta(a[0], a[1]),
        "lbeta" => specials::lbeta(a[0], a[1]),
        "poch" => specials::poch(a[0], a[1]),
        "lgam1p" => specials::lgam1p(a[0]),
        "binom" => specials::binom(a[0], a[1]),
        "zetac" => specials::zetac(a[0]),
        "trigamma" => specials::trigamma(a[0]),
        "digammainv" => specials::digammainv(a[0]),
        "gen_harmonic" => specials::gen_harmonic(a[0], a[1]),
        "stirling2" => specials::stirling2(a[0], a[1]),
        "ellipk" => specials::ellipk(a[0]),
        "ellipkm1" => specials::ellipkm1(a[0]),
        "ellipe" => specials::ellipe(a[0]),
        "ellipkinc" => specials::ellipkinc(a[0], a[1]),
        "ellipeinc" => specials::ellipeinc(a[0], a[1]),
        "ellipj_sn" => specials::ellipj(a[0], a[1]).0,
        "ellipj_cn" => specials::ellipj(a[0], a[1]).1,
        "ellipj_dn" => specials::ellipj(a[0], a[1]).2,
        "ellipj_ph" => specials::ellipj(a[0], a[1]).3,
        "elliprc" => specials::elliprc(a[0], a[1]),
        "elliprf" => specials::elliprf(a[0], a[1], a[2]),
        "elliprd" => specials::elliprd(a[0], a[1], a[2]),
        "elliprj" => specials::elliprj(a[0], a[1], a[2], a[3]),
        "elliprg" => specials::elliprg(a[0], a[1], a[2]),
        "agm" => specials::agm(a[0], a[1]),
        _ => unreachable!("{name}"),
    }
}

/// Tolerances: (function, f64 vs mpmath, f64 vs SciPy, Df64 vs mpmath, absolute floor for f64).
///
/// The f64 figures are those of Cephes as SciPy ships it: `beta` and `lbeta`
/// go through exp/differences of ln Γ for large arguments, and `lgamma` is
/// accurate in absolute terms near its zeros at 1 and 2 (floor 1).
const TOL: [(&str, f64, f64, f64, f64); 30] = [
    ("gamma", 1e-15, 1e-15, 1e-29, 0.0),
    ("lgamma", 1e-15, 1e-15, 1e-29, 1.0),
    ("rgamma", 1e-15, 1e-15, 1e-29, 0.0),
    ("digamma", 2e-15, 1e-15, 1e-29, 0.0),
    ("zeta", 1e-15, 1e-15, 1e-29, 0.0),
    ("beta", 5e-13, 5e-13, 1e-29, 0.0),
    ("lbeta", 1e-13, 4e-15, 2e-29, 0.0),
    // The rest of the gamma family (#8). Worst measured (f64 vs mpmath, f64 vs
    // SciPy, Df64 vs mpmath): poch 1.6e-13 / 1.2e-16 / 9.4e-31, lgam1p 6.3e-16 /
    // see `scipy_comparable` / 4.8e-31, binom see `f64_tolerance` / 3.9e-16 /
    // 1.4e-29, zetac 3.3e-14 / - / 2.1e-29, trigamma 3.6e-16 / 2.1e-16 /
    // 2.4e-31, digammainv 7.6e-16 / - / 3.3e-31, gen_harmonic 1.4e-13 / - /
    // 1.6e-31, stirling2 see `f64_tolerance` / - / 1.4e-31. The stated figures
    // are 3x or more above those.
    //
    // poch, zetac and gen_harmonic evaluate exp/ln of sums of size up to 1e3
    // in f64 (error ~ |ln| eps ~ 1e-13, as xsf). binom and zetac in Df64 reach
    // ~1e-29 where ln Γ or log-form reflection (x < -160) is involved.
    ("poch", 5e-13, 1e-15, 1e-29, 0.0),
    ("lgam1p", 2e-15, 5e-14, 1e-29, 0.0),
    ("binom", 1e-13, 1e-13, 5e-29, 0.0),
    ("zetac", 1e-13, 1e-13, 5e-29, 0.0),
    ("trigamma", 1.1e-15, 2e-15, 1e-30, 0.0),
    ("digammainv", 3e-15, 3e-15, 1e-30, 0.0),
    ("gen_harmonic", 5e-13, 5e-13, 1e-30, 0.0),
    ("stirling2", 1e-12, 1e-12, 1e-30, 0.0),
    // The elliptic family (#11). Worst measured (f64 vs mpmath, f64 vs SciPy,
    // Df64 vs mpmath): ellipk 2.1e-16 / 2.1e-16 / 4.0e-32, ellipkm1 2.1e-16 /
    // 1.7e-16 / 5.7e-32, ellipe 2.5e-16 / 1.5e-16 / 4.5e-32, ellipkinc 2.8e-15 /
    // 4.5e-16 / 1.1e-31, ellipeinc 6.2e-16 / 4.0e-16 / 2.6e-31, elliprc 2.4e-16 /
    // 1.5e-16 / 3.9e-32, elliprf 2.1e-16 / 2.2e-16 / 5.7e-32, elliprd 3.3e-16 /
    // 2.2e-16 / 7.1e-32, elliprj 5.1e-15 / 4.2e-16 / 2.2e-31, elliprg 3.1e-16 /
    // 2.2e-16 / 7.9e-32, agm 2.2e-16 / 2.2e-16 / 4.0e-32. ellipj_sn, _cn and
    // _dn are compared with an absolute floor (`f64_floor`, `jacobi_scale`), so
    // their relative tolerance applies away from the zeros; ellipj_ph for
    // `m >= 0.9999999999` is `2 atan(e^u) - pi/2`, which has an absolute error
    // of 1e-17 (1e-12 relative at u = 1e-5).
    ("ellipk", 1e-15, 1e-15, 5e-30, 0.0),
    ("ellipkm1", 1e-15, 1e-15, 1e-30, 0.0),
    ("ellipe", 1e-15, 1e-15, 1e-30, 0.0),
    ("ellipkinc", 1e-14, 2e-15, 1e-30, 0.0),
    ("ellipeinc", 3e-15, 2e-15, 1e-30, 0.0),
    ("ellipj_sn", 1e-13, 1e-13, 1e-29, 0.0),
    ("ellipj_cn", 1e-13, 1e-13, 1e-29, 0.0),
    ("ellipj_dn", 1e-13, 1e-13, 1e-29, 0.0),
    ("ellipj_ph", 5e-12, 1e-14, 5e-30, 0.0),
    ("elliprc", 1e-15, 1e-15, 1e-30, 0.0),
    ("elliprf", 1e-15, 1e-15, 1e-30, 0.0),
    ("elliprd", 1e-15, 1e-15, 1e-30, 0.0),
    ("elliprj", 2e-14, 2e-15, 1e-30, 0.0),
    ("elliprg", 1e-15, 1e-15, 1e-30, 0.0),
    ("agm", 1e-15, 1e-15, 1e-30, 0.0),
];

/// The f64 tolerance against mpmath, where it depends on the arguments.
///
/// * `binom` with `k > 1e8 |n|` and `k < 1e6` uses xsf's large-`k` asymptotic
///   expansion although `k` is not large (relative error 2.7e-10 at
///   `binom(1e-9, 0.5)`, see `docs/upstream-issues.md`).
/// * `binom` otherwise goes through B(n-k+1, k+1) as exp of a difference of
///   ln Γ values (xsf's `beta`), so its error is a few `eps |ln Γ|`:
///   `3 eps (|ln Γ(n+1)| + |ln Γ(k+1)| + |ln Γ(n-k+1)|)`, at least 1e-13.
/// * `stirling2` for `n > 219` is xsf's second-order Temme approximation
///   (worst 7.4e-7 at n = 220); for `n <= 219` it is the exact recurrence.
fn f64_tolerance(name: &str, a: &[f64], tol: f64) -> f64 {
    match name {
        "binom" if a[1] > 1e8 * a[0].abs() && a[1] < 1e6 => 1e-9,
        "binom" => {
            let l = |x: f64| specials::lgamma(x).abs();
            let l = if l(a[0] + 1.0).is_finite()
                && l(a[1] + 1.0).is_finite()
                && l(a[0] - a[1] + 1.0).is_finite()
            {
                l(a[0] + 1.0) + l(a[1] + 1.0) + l(a[0] - a[1] + 1.0)
            } else {
                0.0
            };
            tol.max(3.0 * f64::EPSILON * l)
        }
        "stirling2" if a[0] > 219.0 => 2e-6,
        _ => tol,
    }
}

/// False where the SciPy 1.16.3 used for the parity column predates a fix that
/// xsf (the pinned commit) has: `lgam1p` near |x| = 1/2 (gh-348, 3e-14),
/// `zetac(x)` for x >= 127 (gh-346, returned 0), `binom` for `k > 1e8 |n|`
/// (gh-352), and `stirling2` for `n > 50` (gh-378, Temme at 2e-5). Those rows
/// are still checked against mpmath.
fn scipy_comparable(name: &str, a: &[f64]) -> bool {
    match name {
        "zetac" => a[0] < 127.0,
        "binom" => a[1] <= 1e8 * a[0].abs(),
        "stirling2" => a[0] <= 50.0,
        // SciPy 1.16.3 returns NaN for a negative parameter (added to xsf later).
        "ellipj_sn" | "ellipj_cn" | "ellipj_dn" | "ellipj_ph" => a[1] >= 0.0,
        // gh-467: SciPy 1.16.3 returns NaN or -inf when y z underflows with x = 0 or subnormal.
        "elliprf" => {
            let mut v = [a[0], a[1], a[2]];
            v.sort_by(f64::total_cmp);
            v[1] * v[2] >= f64::MIN_POSITIVE
        }
        _ => true,
    }
}

/// False where xsf's `f64` `ellipj` for `m >= 0.9999999999` is outside the
/// validity of its expansion in `1 - m`: `cosh(u)` overflows for `|u| > 710`
/// (NaN), and the expansion needs `(1 - m) e^(2|u|)` small (the Cephes
/// header: "the approximation applies only for phi < pi/2"). See
/// `docs/upstream-issues.md`.
fn ellipj_expansion_valid(name: &str, a: &[f64]) -> bool {
    !name.starts_with("ellipj_")
        || a[1] < 0.9999999999
        || (a[0].abs() <= 700.0 && (1.0 - a[1]) * (2.0 * a[0].abs()).exp() <= 1e-3)
}

/// The error criterion of an `f64` Jacobi function: relative `tol`, or an
/// absolute `100 eps scale` (see `refdata::jacobi_scale`; xsf: "accuracy
/// deteriorates when u is large", worst measured 56 eps scale).
fn f64_floor(name: &str, a: &[f64], reference: f64, tol: f64, floor: f64) -> f64 {
    let scale = refdata::jacobi_scale(name, a[0], a.get(1).copied().unwrap_or(0.0), reference);
    floor.max(refdata::jacobi_floor(scale, 100.0, f64::EPSILON, tol))
}

#[test]
fn f64_matches_mpmath_and_scipy() {
    for (name, tol_mp, tol_sp, _, floor) in TOL {
        for r in rows(name).iter().filter(|r| r.is_f64()) {
            let a: Vec<f64> = r.args_as();
            let got = eval(name, &a);
            let tol_mp = f64_tolerance(name, &a, tol_mp);
            if ellipj_expansion_valid(name, &a) {
                let e = error(
                    got,
                    r.reference,
                    f64_floor(name, &a, r.reference.0, tol_mp, floor),
                );
                assert!(
                    e <= tol_mp,
                    "{name}{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
                    r.line,
                    r.reference
                );
            }
            // digammainv and gen_harmonic are not in SciPy 1.16.3 (no value).
            if let Some(s) = r.scipy.filter(|_| scipy_comparable(name, &a)) {
                let e = error(got, (s, 0.0), f64_floor(name, &a, s, tol_sp, floor));
                assert!(
                    e <= tol_sp,
                    "{name}{a:?} (line {}): got {got:e}, scipy {s:e}, err {e:e}",
                    r.line
                );
            }
        }
    }
}

#[cfg(feature = "xprec")]
#[test]
fn df64_matches_mpmath() {
    for (name, _, _, tol, _) in TOL {
        for r in rows(name) {
            let a: Vec<Df64> = r.args_as();
            let got = eval(name, &a);
            // Absolute error 24 ε scale, ε = 2^-105 (measured worst 8.3 ε scale).
            let scale = refdata::jacobi_scale(
                name,
                r.args[0].0,
                r.args.get(1).map_or(0.0, |p| p.0),
                r.reference.0,
            );
            let e = error(
                got,
                r.reference,
                refdata::jacobi_floor(scale, 24.0, 2.0_f64.powi(-105), tol),
            );
            assert!(
                e <= tol,
                "{name}{:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
                r.args,
                r.line,
                r.reference
            );
        }
    }
}

#[test]
fn special_values_match_scipy() {
    for (name, args, expected) in special_values() {
        let got = eval::<f64>(&name, &args);
        assert!(
            same(got, expected),
            "f64 {name}{args:?} = {got}, scipy {expected}"
        );
        #[cfg(feature = "xprec")]
        {
            let a: Vec<Df64> = args.iter().map(|&x| Df64::from(x)).collect();
            let got = eval::<Df64>(&name, &a);
            assert!(
                same(got, expected),
                "Df64 {name}{args:?} = {got:?}, scipy {expected}"
            );
        }
    }
}

/// `S(n, n-3) = C(n,4) + 10 C(n,5) + 15 C(n,6)` in f64 (relative error ~1e-15 for the n used).
fn stirling2_n_minus_3(n: f64) -> f64 {
    let c = |j: u32| (0..j).fold(1.0, |acc, i| acc * (n - f64::from(i)) / f64::from(i + 1));
    c(4) + 10.0 * c(5) + 15.0 * c(6)
}

/// The `f64` assertion runs in every configuration, the `Df64` ones with `xprec`.
#[test]
fn stirling2_df64_beyond_the_work_limit_is_exact() {
    // (k-1)(n-k) = 3.6e7 > 3e7, beyond the recurrence: n - k = 3 <= 64 takes the
    // exact sum of `near_diagonal` in both strategies (xsf's Temme gave NaN for
    // small n - k and large n). The reference is the closed form for S(n, n-3)
    // evaluated in f64.
    let (n, k) = (1.2e7, 1.2e7 - 3.0);
    let exact = stirling2_n_minus_3(n);
    #[cfg(feature = "xprec")]
    {
        let df = specials::stirling2(Df64::from(n), Df64::from(k));
        let e = (df.hi() - exact).abs() / exact;
        assert!(
            e < 1e-14,
            "S({n}, {k}): {:e} vs {exact:e}, error {e:e}",
            df.hi()
        );
    }
    let f = specials::stirling2(n, k);
    assert!(
        ((f - exact) / exact).abs() < 1e-14,
        "f64 S({n}, {k}) = {f:e}"
    );
    // Within the limit (cost 6e5): the exact recurrence, to double-double.
    #[cfg(feature = "xprec")]
    {
        let (n, k) = (2e5, 2e5 - 3.0);
        let df = specials::stirling2(Df64::from(n), Df64::from(k));
        let exact = stirling2_n_minus_3(n);
        assert!(
            (df.hi() - exact).abs() / exact < 1e-14,
            "f64 formula limits the check"
        );
    }
}

/// R_J(x, y, z, z) = R_D(x, y, z) (DLMF 19.20.? degenerate case). The `Df64`
/// R_J is accurate up to a ratio of 2^600 between its largest and smallest
/// nonzero argument and returns NaN beyond it, instead of a wrong value.
#[cfg(feature = "xprec")]
#[test]
fn df64_elliprj_ratio_limit_is_fail_fast() {
    let d = Df64::from;
    for z in [1e100, 1e150, 1e180] {
        let rj = specials::elliprj(d(0.5), d(1.0), d(z), d(z));
        let rd = specials::elliprd(d(0.5), d(1.0), d(z));
        let e = ((rj - rd) / rd).abs().hi();
        assert!(
            e <= 1e-29,
            "z={z:e}: R_J = {rj:?}, R_D = {rd:?}, error {e:e}"
        );
    }
    for z in [1e182, 1e200, 1e300] {
        assert!(
            specials::elliprj(d(0.5), d(1.0), d(z), d(z)).hi().is_nan(),
            "z={z:e}"
        );
    }
    // A zero argument does not count: R_J(0, y, z, p) has a ratio of y/z only.
    assert!(specials::elliprj(d(0.0), d(1.0), d(1e150), d(2.0))
        .hi()
        .is_finite());
}
